cd /workspace && cat > boot.mjs <<'EOF'
import { JSDOM } from 'jsdom';
import fs from 'fs';
const html = fs.readFileSync('/workspace/dist/basic/index.html','utf8');
const dom = new JSDOM(html, {url:'http://localhost:8099/basic/index.html', pretendToBeVisual:true, resources:'usable'});
const w = dom.window;
for (const k of ['window','document','navigator','HTMLElement','Node','customElements','MutationObserver','CustomEvent','Event','getComputedStyle','DOMParser','XMLHttpRequest','CSS','history','location','screen','localStorage','sessionStorage','matchMedia','ResizeObserver','IntersectionObserver','Blob','URL','Image','HTMLCanvasElement','performance']) {
  try { if (k in w) globalThis[k] = w[k]; } catch {}
}
globalThis.requestAnimationFrame = (cb)=>setTimeout(()=>cb(Date.now()),0);
globalThis.cancelAnimationFrame = (id)=>clearTimeout(id);
globalThis.fetch = async (u)=>({ok:true,status:200,json:async()=>({}),text:async()=>'{}',headers:{get:()=>null}});
// languages loaded via i18n http backend mock
const bundle = fs.readFileSync('/workspace/dist/mastercode/3_26_1_410dc25_git_last_commit_at_2026-09-23__10-05-39/js/masterportal.js','utf8');
process.on('unhandledRejection',e=>console.log('UNHANDLED_REJ:', String(e).slice(0,200)));
const t=setTimeout(()=>{console.log('TIMEOUT_STILL_RUNNING'); process.exit(2);},60000);
try {
  await import('data:text/javascript;base64,'+Buffer.from(bundle).toString('base64'));
  console.log('MODULE_IMPORTED_OK');
} catch(e){ console.log('IMPORT_ERR:', e.constructor.name, String(e.message).slice(0,300)); }
clearTimeout(t);
await new Promise(r=>setTimeout(r,3000));
console.log('__appMounted =', w.__appMounted);
const root=w.document.getElementById('masterportal-root');
console.log('root children:', root? root.children.length : 'no-root');
console.log('root innerHTML len:', root? root.innerHTML.length : 0);
process.exit(0);
EOF
timeout 120 node boot.mjs; echo "EXIT=$?"; rm -f boot.mjs
